-- ============================================================================
-- Fecha Mudança no uso do solo (Escopo 1): método detalhado (Tabela 1),
-- diferença de estoque de carbono entre uso anterior e posterior do solo.
-- Até aqui só existia o relato direto por gás (Tabela 3, Fase A).
--
-- Csolo = SOCref × FLU × FMG × FI; Cbm = Cveg — por estado × categoria de uso
-- do solo (8 categorias × 27 estados = 216 linhas), extraídos de
-- Listas!CZ317:DJ559 (fonte BRLUC v1.3) via
-- scripts/extract_ghg_factors.py --lulucf. Emissão/remoção =
-- (estoque_anterior − estoque_posterior) × 44/12 × área; a REMOÇÃO de
-- biomassa amortiza em 20 anos quando o uso posterior é de crescimento lento
-- (vegetação natural/silvicultura, ou cultura perene com biomassa lenhosa) —
-- emissões nunca amortizam. Ver calcLandUseDetailed em registry.ts.
--
-- Simplificação Fase A (documentada em LandUseData, types.ts): usa a
-- categoria de vegetação natural direto da tabela por estado, sem descer ao
-- nível de fitofisionomia por bioma (refinamento opcional da planilha) nem
-- aceitar override manual de estoque de carbono via dados primários.
-- ============================================================================

create table ghg_lulucf_state_factors (
  id uuid primary key default gen_random_uuid(),
  uf text not null,
  state_name text not null,
  land_use_category text not null,
  socref numeric not null,
  flu numeric not null default 1,
  fmg numeric not null default 1,
  fi numeric not null default 1,
  cveg numeric not null default 0,
  source text,
  unique (uf, land_use_category)
);

alter table ghg_lulucf_state_factors enable row level security;
create policy ghg_lulucf_state_factors_read on ghg_lulucf_state_factors for select to authenticated using (true);


